package com.farika.soundflow;
import android.app.*;import android.app.job.*;import android.content.*;import android.graphics.*;import android.os.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.security.*;import java.io.*;import java.time.Duration;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=android.app.Application.class)
public class QuietChecks165Test {
 Context c;NotificationManager manager;FakeApi api;FakeStore store;ArrayList<Library.Track> tracks;int transfers;ArrayList<String> labels;boolean beforeTransfer;
 @Before public void setup()throws Exception{ResidentChecks.resetForTest();c=RuntimeEnvironment.getApplication();c.getSharedPreferences("profile",0).edit().putString("id","123").commit();Provider p=new Provider("VolnaSyntheticKeyStore",1.0,"test only"){};p.put("KeyStore.AndroidKeyStore",WarmWriterTest.MemoryStore.class.getName());Security.insertProviderAt(p,1);Session.put(c,"OAuth SYNTHETIC_165_TOKEN_12345","SYNTHETIC_165_CLIENT_12345");manager=c.getSystemService(NotificationManager.class);manager.cancelAll();tracks=new ArrayList<>();labels=new ArrayList<>();api=new FakeApi();store=new FakeStore();}
 @After public void cleanup(){ResidentChecks.resetForTest();Security.removeProvider("VolnaSyntheticKeyStore");}
 Library.Track track(int id)throws Exception{Library.Track t=new Library.Track("sc:"+id,"track "+id,"artist",180000,true);t.remote=new JSONObject().put("id",""+id).put("full_duration",180000);return t;}
 Library.Track copy(Library.Track t){Library.Track copy=new Library.Track("offline:"+UUID.randomUUID(),t.title,t.artist,t.duration,t.liked);copy.remote=t.remote;return copy;}
 void prepare(int total,int ready)throws Exception{for(int i=0;i<total;i++){Library.Track t=track(i);tracks.add(t);if(i<ready)store.copies.add(copy(t));}try(SyncDb db=new SyncDb(c)){db.ensure("123","likes","Любимое","favorites");db.auto("123","likes",true);db.snapshot("123","likes",tracks);for(int i=0;i<ready;i++)db.sourceReady("123",""+i);}}
 class FakeApi extends ScApi {int reads,art;boolean fail;FakeApi(){super(QuietChecks165Test.this.c);}public Page likes(String user,String next)throws Exception{reads++;if(fail)throw new IOException("fixture offline");Page p=new Page();p.tracks.addAll(tracks);return p;}public Bitmap artwork(String url){art++;return Bitmap.createBitmap(16,16,Bitmap.Config.ARGB_8888);}}
 class FakeStore extends OfflineStore {int saves;boolean visibleDuringSave,activeDuringSave;HashSet<String> excluded=new HashSet<>();ArrayList<Library.Track> copies=new ArrayList<>();FakeStore(){super(QuietChecks165Test.this.c);}public ArrayList<Library.Track> list(){return copies;}public boolean excluded(String id){return excluded.contains(id);}public Library.Track save(Library.Track t,Progress p)throws Exception{saves++;visibleDuringSave=Shadows.shadowOf(manager).getNotification(DownloadNotice.ID)!=null;activeDuringSave=DownloadActivityState.active("123");if(p.cancelled())throw new InterruptedIOException();p.update(50);p.update(100);Library.Track saved=copy(t);copies.add(saved);return saved;}}
 DownloadSync.Monitor monitor(){DownloadNotice notice=new DownloadNotice(c,"Любимое");return new DownloadSync.Monitor(){public boolean cancelled(){return false;}public void progress(String s,int p){notice.progress(s,p);}public void transfer(String s,int p){transfers++;labels.add(s);notice.transfer(s,p);}public void finished(){notice.close();}};}
 String run(boolean refresh,boolean force,DownloadSync.Monitor monitor)throws Exception{return DownloadSync.run(c,"123","likes","Любимое","favorites",refresh,force,monitor,api,store);}
 @Test public void unchanged164TracksProduceNoNotificationOrSave()throws Exception{prepare(164,164);String result=run(true,false,monitor());assertEquals(1,api.reads);assertEquals(0,store.saves);assertEquals(0,transfers);assertFalse(DownloadActivityState.active("123"));assertNull(Shadows.shadowOf(manager).getNotification(8));assertTrue(result.startsWith("Проверено без скачивания"));}
 @Test public void onlyNewTrackAppearsInDownloadCounter()throws Exception{prepare(165,164);run(true,false,monitor());assertEquals(1,store.saves);assertEquals(1,transfers);assertTrue(labels.get(0).startsWith("1 / 1"));assertTrue(store.visibleDuringSave);assertTrue(store.activeDuringSave);assertNull(Shadows.shadowOf(manager).getNotification(8));assertFalse(DownloadActivityState.active("123"));}
 @Test public void twoMissingTracksCountAsTwoNotAll166()throws Exception{prepare(166,164);run(false,false,monitor());assertEquals(2,store.saves);assertTrue(labels.get(0).startsWith("1 / 2"));assertTrue(labels.get(1).startsWith("2 / 2"));assertEquals(0,api.reads);}
 @Test public void emptyConfirmedListHasNoNotification()throws Exception{prepare(0,0);run(true,false,monitor());assertEquals(0,transfers);assertNull(Shadows.shadowOf(manager).getNotification(8));}
 @Test public void metadataFailureHasNoNotification()throws Exception{prepare(1,1);api.fail=true;try{run(true,false,monitor());fail();}catch(IOException expected){}assertNull(Shadows.shadowOf(manager).getNotification(8));assertEquals(0,store.saves);}
 @Test public void coversAlreadyPresentAreNotRequestedAgain()throws Exception{prepare(1,1);String url="https://i1.sndcdn.com/quiet-existing.jpg";tracks.get(0).remote.put("artwork_url",url);assertTrue(OfflineArt.save(c,api,url));api.art=0;run(false,false,monitor());assertEquals(0,api.art);assertEquals(0,transfers);}
 @Test public void missingCoverIsARealTransferWithoutAudioRedownload()throws Exception{prepare(1,1);tracks.get(0).remote.put("artwork_url","https://i1.sndcdn.com/quiet-missing.jpg");run(false,false,monitor());assertEquals(1,api.art);assertEquals(0,store.saves);assertEquals(1,transfers);assertTrue(labels.get(0).startsWith("Обложка · 1 / 1"));assertNull(Shadows.shadowOf(manager).getNotification(8));}
 @Test public void artworkBackoffDoesNotCreateNotification()throws Exception{prepare(1,1);tracks.get(0).remote.put("artwork_url","https://i1.sndcdn.com/quiet-backoff.jpg");try(SyncDb db=new SyncDb(c)){db.state("123","likes","0","RETRY","ARTWORK_PENDING");db.retry("123","likes","0",System.currentTimeMillis()+900000);}run(false,false,monitor());assertEquals(0,api.art);assertEquals(0,transfers);}
 @Test public void pendingErrorInBackoffIsNotReportedAsDownloading()throws Exception{prepare(1,0);try(SyncDb db=new SyncDb(c)){db.state("123","likes","0","BLOCKED","PREVIEW_ONLY");db.retry("123","likes","0",System.currentTimeMillis()+21600000);}run(false,false,monitor());assertEquals(0,store.saves);assertEquals(0,transfers);}
 @Test public void excludedTrackIsNotNotified()throws Exception{prepare(1,0);store.excluded.add("0");run(false,false,monitor());assertEquals(0,store.saves);assertEquals(0,transfers);}
 @Test public void quietProbeHandsNewFilesToDurableQueue()throws Exception{prepare(2,1);DownloadSync.Monitor probe=new DownloadSync.Monitor(){public boolean cancelled(){return false;}public void progress(String s,int p){}public boolean beforeTransfers(int count){beforeTransfer=true;assertEquals(1,count);return false;}};run(true,false,probe);assertTrue(beforeTransfer);assertEquals(0,store.saves);assertNull(Shadows.shadowOf(manager).getNotification(8));try(SyncDb db=new SyncDb(c)){assertTrue(db.plans("123",false).get(0).optBoolean("active"));assertEquals(1,db.totals("123","likes")[3]);}run(false,false,monitor());assertEquals(1,api.reads);assertEquals(1,store.saves);assertTrue(store.visibleDuringSave);}
 @Test public void checkDoesNotRemovePlaybackNotification()throws Exception{prepare(1,1);manager.createNotificationChannel(new NotificationChannel("play","Play",2));manager.notify(7,new Notification.Builder(c,"play").setSmallIcon(android.R.drawable.ic_media_play).build());run(true,false,monitor());assertNotNull(Shadows.shadowOf(manager).getNotification(7));assertNull(Shadows.shadowOf(manager).getNotification(8));}
 @Test public void pendingRequestPersistsAndMergesRetryIntent(){SyncRequests.put(c,"123","likes",true,false,false);SyncRequests.Request first=SyncRequests.get(c,"123","likes");SyncRequests.put(c,"123","likes",false,true,true);SyncRequests.Request second=SyncRequests.get(c,"123","likes");assertTrue(second.refresh);assertTrue(second.force);assertTrue(second.manual);SyncRequests.consume(c,"123","likes",first);assertTrue(SyncRequests.pending(c,"123","likes"));SyncRequests.consume(c,"123","likes",second);assertFalse(SyncRequests.pending(c,"123","likes"));assertFalse(SyncRequests.any(c,"other",false));}
 @Test public void completedAutoPlanNeverSchedulesWakeupCheck()throws Exception{prepare(2,2);AutoDownloads.schedule(c);AutoDownloads.kick(c);AutoDownloads.retry(c);assertTrue(c.getSystemService(JobScheduler.class).getAllPendingJobs().isEmpty());try(SyncDb db=new SyncDb(c)){assertFalse(CheckCadence.runnable(c,db,"123",db.plans("123",false).get(0),System.currentTimeMillis()));}}
 @Test public void obsoletePeriodicJobIsRemoved()throws Exception{prepare(1,1);JobScheduler jobs=c.getSystemService(JobScheduler.class);jobs.schedule(new JobInfo.Builder(501,new ComponentName(c,AutoDownloadJob.class)).setPeriodic(900000).build());assertNotNull(jobs.getPendingJob(501));AutoDownloads.schedule(c);assertNull(jobs.getPendingJob(501));}
 @Test public void resumeJobDoesNotRefreshCompletedSnapshotJustBecauseTimePassed()throws Exception{prepare(1,0);try(SyncDb db=new SyncDb(c)){JSONObject p=db.plans("123",false).get(0);assertTrue(CheckCadence.runnable(c,db,"123",p,System.currentTimeMillis()));assertFalse(CheckCadence.refresh(c,"123",p,new SyncRequests.Request(),System.currentTimeMillis()));}assertFalse(ResidentChecks.running());}
 @Test public void networkEventDoesNotCheckFinishedAutoPlan()throws Exception{prepare(1,1);for(int i=0;i<5;i++)AutoDownloads.kick(c);assertTrue(c.getSystemService(JobScheduler.class).getAllPendingJobs().isEmpty());assertEquals(0,api.reads);}
 @Test public void cadenceRejectsRepeatedChecksBeforeFifteenMinutes(){long now=System.currentTimeMillis();assertTrue(CheckCadence.due(c,"123","likes",now));CheckCadence.attempted(c,"123","likes");assertFalse(CheckCadence.due(c,"123","likes",now+899000));assertTrue(CheckCadence.due(c,"123","likes",now+900100));assertTrue(CheckCadence.due(c,"other","likes",now));}
 void waitFor(java.util.function.BooleanSupplier test)throws Exception{for(int i=0;i<300&&!test.getAsBoolean();i++){Shadows.shadowOf(Looper.getMainLooper()).idle();Thread.sleep(10);}assertTrue(test.getAsBoolean());Thread.sleep(20);Shadows.shadowOf(Looper.getMainLooper()).idle();}
 @Test public void residentTimerWaitsFifteenMinutesAndDoesNotRestartOnScreenOpen()throws Exception{AtomicInteger count=new AtomicInteger();ResidentChecks.start(c,count::incrementAndGet);ResidentChecks.start(c,()->fail("duplicate timer"));assertEquals(0,count.get());Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMinutes(14));assertEquals(0,count.get());Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMinutes(1));waitFor(()->count.get()==1);assertTrue(c.getSystemService(JobScheduler.class).getAllPendingJobs().isEmpty());Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMinutes(14));assertEquals(1,count.get());Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMinutes(1));waitFor(()->count.get()==2);}
 @Test public void losingResidentTimerDoesNotArrangeSystemRestart(){AtomicInteger count=new AtomicInteger();ResidentChecks.start(c,count::incrementAndGet);ResidentChecks.resetForTest();Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMinutes(40));assertEquals(0,count.get());assertFalse(ResidentChecks.running());assertTrue(c.getSystemService(JobScheduler.class).getAllPendingJobs().isEmpty());}
 @Test public void openingDownloadsScreenDoesNotRequestImmediateCheck()throws Exception{prepare(1,1);org.robolectric.android.controller.ActivityController<AutoDownloadActivity> ctrl=Robolectric.buildActivity(AutoDownloadActivity.class).setup();assertTrue(ResidentChecks.running());assertFalse(SyncRequests.pending(c,"123","likes"));assertTrue(c.getSystemService(JobScheduler.class).getAllPendingJobs().isEmpty());assertNull(Shadows.shadowOf(manager).getNotification(8));ctrl.pause().stop().destroy();}
 @Test public void cancelStopsNotificationAndLateProgressCannotRestoreIt(){DownloadNotice notice=new DownloadNotice(c,"Actual");notice.transfer("1 / 1",0);assertNotNull(Shadows.shadowOf(manager).getNotification(8));new CancelDownloadsReceiver().onReceive(c,new Intent());assertNull(Shadows.shadowOf(manager).getNotification(8));notice.progress("late",90);assertNull(Shadows.shadowOf(manager).getNotification(8));notice.close();}
 @Test public void metadataProgressAloneCannotPostNotification(){DownloadNotice notice=new DownloadNotice(c,"Quiet");notice.progress("Проверка списка",0);notice.close();assertNull(Shadows.shadowOf(manager).getNotification(8));}
 @Test public void quietProbeMarksMissingCoverAsPendingForTransferJob()throws Exception{prepare(1,1);tracks.get(0).remote.put("artwork_url","https://i1.sndcdn.com/probe-cover.jpg");run(false,false,new DownloadSync.Monitor(){public boolean cancelled(){return false;}public void progress(String text,int percent){}public boolean beforeTransfers(int count){return false;}});try(SyncDb db=new SyncDb(c)){assertEquals(1,db.totals("123","likes")[3]);assertTrue(CheckCadence.runnable(c,db,"123",db.plans("123",false).get(0),System.currentTimeMillis()));}assertEquals(0,api.art);assertNull(Shadows.shadowOf(manager).getNotification(8));run(false,false,monitor());assertEquals(1,api.art);}
 @Test public void explicitDownloadQueuesWithoutForegroundPreparationNotification()throws Exception{android.app.Activity activity=Robolectric.buildActivity(android.app.Activity.class).setup().get();Library library=new Library(c);Library.Track t=track(123);library.upsert(t);library.save();DownloadActions.start(activity,"track:123","Track","track",true,true);assertNull(Shadows.shadowOf(activity).getNextStartedService());assertNull(Shadows.shadowOf(manager).getNotification(8));SyncRequests.Request r=SyncRequests.get(c,"123","track:123");assertTrue(r.refresh);assertTrue(r.force);assertTrue(r.manual);activity.finish();}

}
